import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], *, workers: int = 4) -> int:
    """Sum of x*x over xs, with the squares computed in a thread pool.

    The result is exact (Python ints) and identical for every worker count.
    An empty list gives 0. Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives() -> None:
    assert sum_squares([-3, 3, -1]) == 19


def test_does_not_mutate_input() -> None:
    xs = [3, -2, 5]
    sum_squares(xs)
    assert xs == [3, -2, 5]


def test_big_ints_exact() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 16, 100])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 200))
    expected = sum(square(x) for x in xs)
    assert sum_squares(xs, workers=workers) == expected


def test_more_workers_than_items() -> None:
    assert sum_squares([2, 3], workers=32) == 13


def test_default_matches_explicit_workers() -> None:
    xs = [5, -4, 9, 0, 11]
    assert sum_squares(xs) == sum_squares(xs, workers=1)


def test_large_list_matches_sequential() -> None:
    xs = [(i * 7919) % 1001 - 500 for i in range(5000)]
    expected = sum(x * x for x in xs)
    for w in (1, 2, 5, 13):
        assert sum_squares(xs, workers=w) == expected


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2, 3], workers=workers)
